{"function":"() => {
const td = document.querySelector('tbody tr td:nth-child(9)');
const out = [];
td.querySelectorAll('br-button').forEach(b => {
  const inner = b.shadowRoot ? b.shadowRoot.querySelector('button') : b.querySelector('button');
  out.push({host: b.outerHTML.slice(0,300), parent: b.parentElement.outerHTML.slice(0,200), inner: inner ? inner.outerHTML.slice(0,300) : null, shadow: !!b.shadowRoot});
});
return out;
}"}

