const r={};
const hdr = document.querySelector('br-header');
r.headerHost = hdr ? hdr.outerHTML.slice(0,300):null;
const sr = hdr && hdr.shadowRoot;
r.headerImg = sr ? [...sr.querySelectorAll('img')].map(i=>i.outerHTML) : [...document.querySelectorAll('header img')].map(i=>i.outerHTML);
r.menuBtn = sr ? [...sr.querySelectorAll('button')].map(b=>b.outerHTML.slice(0,250)) : null;
const av = document.querySelector('#avatar-dropdown-trigger') || [...document.querySelectorAll('button')].find(b=>/Avatar/.test(b.getAttribute('aria-label')||''));
r.avatar = av ? av.outerHTML.slice(0,600) : null;
r.avatarMenu = document.querySelector('#avatar-menu')?.outerHTML.slice(0,900);
const bc = document.querySelector('br-breadcrumb');
r.bc = bc ? (bc.shadowRoot? bc.shadowRoot.innerHTML.slice(0,900): bc.innerHTML.slice(0,900)) : null;
r.bcHost = bc?.outerHTML.slice(0,300);
const pag = document.querySelector('nav[aria-label="Paginação de resultados"]');
r.pag = pag?.outerHTML.slice(0,1500);
r.pagHost = pag?.parentElement?.outerHTML.slice(0,200);
r.upd = [...document.querySelectorAll('*')].find(e=>e.childNodes.length && [...e.childNodes].some(n=>n.nodeType==3 && /Última atualização/.test(n.textContent)))?.outerHTML.slice(0,400);
return r;
}"}

