{"function":"() => {
// collect sequential focus order approximation: tabbable elements across shadow roots
const out=[];
function walk(root){
  root.querySelectorAll('*').forEach(el=>{
    if (el.shadowRoot) walk(el.shadowRoot);
    if (el.tabIndex>=0 && !el.disabled && !el.closest('[hidden]') && el.getClientRects().length) out.push(el.tagName+(el.id?'#'+el.id:'')+' '+(el.getAttribute('aria-label')||el.title||el.textContent.trim()).slice(0,30));
  });
}
walk(document);
return out.slice(0,40);
}"}

